"""Luhn algorithm card number validation."""


def valid(number):
    """Return True if *number* passes the Luhn checksum.

    ``number`` is a string. Single spaces between digits are allowed and
    ignored. Return False if, after removing spaces, there are fewer than
    two characters or any character is not a digit 0-9.
    """
    if not isinstance(number, str):
        return False
    digits = number.replace(" ", "")
    if len(digits) < 2:
        return False
    if any(c < "0" or c > "9" for c in digits):
        return False
    total = 0
    for index, char in enumerate(reversed(digits)):
        value = ord(char) - ord("0")
        if index % 2 == 1:
            value *= 2
            if value > 9:
                value -= 9
        total += value
    return total % 10 == 0
